        .write(true)
        .create_new(true)
        .mode(0o600)
        .open(&temp)
        .map_err(StoreError::Io)?;
    let result = (|| {
        file.write_all(&data).map_err(StoreError::Io)?;
        file.sync_all().map_err(StoreError::Io)?;
