//! File locking and atomic archive writes must not occupy async I/O workers.
//! Completion belongs to the real worker even when its HTTP waiter disappears.
use proletarius_store::StoreError;
use std::sync::{Arc, Mutex, OnceLock};
use tokio::sync::Notify;

const ARCHIVE_WORKERS: usize = 8;
const MAX_ORPHAN_ERRORS: usize = 64;
static EXECUTOR: OnceLock<Executor> = OnceLock::new();

pub(crate) async fn run<T: Send + 'static>(
    operation: impl FnOnce() -> Result<T, StoreError> + Send + 'static,
) -> Result<T, StoreError> {
    EXECUTOR
        .get_or_init(|| Executor::new(ARCHIVE_WORKERS))
        .run(operation)
        .await
}

/// Call after stopping external producers. This waits for actual registered
/// workers, including cancelled waiters, rather than queuing an eight-slot
/// pool sentinel. It does not close the pool: the caller may subsequently run
/// its explicitly awaited final call-facts flush.
/// Only errors whose result was never delivered to a waiter are reported.
pub(crate) async fn finish_pending() -> Result<(), String> {
    match EXECUTOR.get() {
        Some(executor) => executor.ledger.finish_pending().await,
        None => Ok(()),
    }
}

struct Executor {
    pool: crate::blocking_pool::BlockingPool,
    ledger: Arc<Ledger>,
}
impl Executor {
    fn new(concurrency: usize) -> Self {
        Self {
            pool: crate::blocking_pool::BlockingPool::new(concurrency),
            ledger: Arc::new(Ledger::default()),
        }
    }

    async fn run<T: Send + 'static>(
        &self,
        operation: impl FnOnce() -> Result<T, StoreError> + Send + 'static,
    ) -> Result<T, StoreError> {
        let completion = self.ledger.register();
        let mut waiter = Waiter {
            completion: completion.clone(),
            delivered: false,
        };
        // The closure owns its completion before it waits for pool capacity.
        // Dropping a never-executed closure confirms cancellation without
        // running the original operation or reporting a spurious failure.
        let mut worker = Worker {
            completion,
            started: false,
            outcome: None,
        };
        let result = self
            .pool
            .run(move || {
                worker.started = true;
                let result = operation();
                worker.outcome = Some(result.as_ref().err().map(ToString::to_string));
                result
            })
            .await
            .map_err(|_| StoreError::Io(std::io::Error::other("archive worker failed")))
            .and_then(|result| result);
        // This synchronous tail runs in the same poll that returns the result.
        // Cancellation before that poll leaves the result owned by the ledger.
        waiter.delivered = true;
        result
    }
}

