/// The first committed checkpoint wins. A concurrent winner or an existing
/// checkpoint is returned unchanged, even if `candidate` differs. Callers
/// must validate the returned bytes rather than assuming their input won.
func confirm(_ candidate: Data) throws -> Data {
    guard candidate.count <= Self.maximumBytes else { throw Failure.tooLarge }
    return try withLock { lock in
        if let bytes = try readConfirmed(lock: lock) { return bytes }
        let temporary = ".sms-forwarding-swift-checkpoint-v1.\(UUID().uuidString.lowercased()).tmp"
        let descriptor = temporary.withCString {
            Darwin.openat(root.descriptor, $0,
                          O_RDWR | O_CREAT | O_EXCL | O_NOFOLLOW | O_CLOEXEC, mode_t(0o600))
        }
        guard descriptor >= 0 else { throw Failure.unavailable }
        defer { _ = Darwin.close(descriptor) }
        // umask may remove owner bits. Only our exclusively created temp
        // is normalized; pre-existing checkpoint/lock modes are immutable.
        guard Darwin.fchmod(descriptor, mode_t(0o600)) == 0 else {
            removeOwnedTemporary(temporary, descriptor: descriptor)
            throw Failure.unavailable
        }
        defer { removeOwnedTemporary(temporary, descriptor: descriptor) }
        try validateRootAndLock(lock)
        _ = try checkedFile(descriptor, name: temporary)
        try candidate.withUnsafeBytes { bytes in
            var offset = 0
            while offset < bytes.count {
                let count = Darwin.write(descriptor, bytes.baseAddress!.advanced(by: offset), bytes.count - offset)
                if count < 0 && errno == EINTR { continue }
                guard count > 0 else { throw Failure.unavailable }
                offset += count
