                .nwait_sms
                .was_enabled
                .or_else(|| (!handoff.nwait_sms.seeded).then_some(forwarding_enabled));
            let progress = Progress {
                schema_version: 1,
                handoff_id: handoff.handoff_id.clone(),
                cursor,
                seeded: true,
                was_enabled,
