    path: PathBuf,
    _lock: Flock<File>,
    key: StateKey,
    limits: StateLimits,
    current: JsonDocument,
    in_flight: HashSet<(String, ForwardingChannel)>,
    telegram_submitting_chunk: HashMap<String, usize>,
    poisoned: bool,
}

