pub(crate) async fn admission_enabled(&self) -> Result<bool, &'static str> {
    let mut state = self.0.state.lock().await;
    if let Some(code) = state.admission_error().await {
        return Err(code);
    }
    // `active == None` has two meanings: an explicitly acknowledged
    // disabled configuration, or the process-start window before the
    // GUI has restored its Keychain-backed configuration. Only the first
    // may advance durable SMS high-water marks or establish a baseline.
    if state.admission.is_none() {
        return Err("sms_forwarding_configuration_unconfirmed");
    }
    Ok(state
        .active
        .as_ref()
        .is_some_and(|active| active.settings.telegram.enabled || active.settings.bark.enabled))
}

func start() -> String? {
    stateLock.lock()
    defer { stateLock.unlock() }
    guard !running else { return nil }
    if !registrations.isEmpty {
        let failure = unregisterIOProcs()
        guard registrations.isEmpty else {
            if !registrations.callbacksMayRun { resetAudioPipeline() }
            return failure.map(retirementMessage) ?? "上一次音频设备清理尚未确认"
        }
        resetAudioPipeline()
    }

func stop() -> String? {
    stateLock.lock()
    defer { stateLock.unlock() }
    let failure = unregisterIOProcs()
    running = false
    if !registrations.callbacksMayRun { resetAudioPipeline() }
    return failure.map(retirementMessage)
}

private func unregisterIOProcs() -> AudioIOProcRetirementFailure? {
    registrations.retire(
        stop: { AudioDeviceStop($0.device, $0.procID) },
        destroy: { AudioDeviceDestroyIOProcID($0.device, $0.procID) },
        release: { Unmanaged<BridgeContext>.fromOpaque($0.context).release() })
}

struct AudioIOProcRetirementLedger<Resource> {
    struct Entry {
        let resource: Resource
        var stopAcknowledged: Bool
    }

    private(set) var entries: [Entry] = []

    var isEmpty: Bool { entries.isEmpty }
    var callbacksMayRun: Bool { entries.contains { !$0.stopAcknowledged } }

    @discardableResult
    mutating func append(_ resource: Resource) -> Int {
        entries.append(Entry(resource: resource, stopAcknowledged: true))
        return entries.count - 1
    }

    mutating func markStarted(at index: Int) {
        precondition(entries.indices.contains(index))
        precondition(entries[index].stopAcknowledged)
        entries[index].stopAcknowledged = false
    }

mutating func retire(
    stop: (Resource) -> Int32,
    destroy: (Resource) -> Int32,
    release: (Resource) -> Void
) -> AudioIOProcRetirementFailure? {
    var firstFailure: AudioIOProcRetirementFailure?

    for index in entries.indices.reversed() {
        let resource = entries[index].resource
        if !entries[index].stopAcknowledged {
            let status = stop(resource)
            guard status == 0 else {
                if firstFailure == nil {
                    firstFailure = AudioIOProcRetirementFailure(operation: .stop, status: status)
                }
                continue
            }
            entries[index].stopAcknowledged = true
        }

        let status = destroy(resource)
        guard status == 0 else {
            if firstFailure == nil {
                firstFailure = AudioIOProcRetirementFailure(operation: .destroy, status: status)
            }
            continue
        }

        release(resource)
        entries.remove(at: index)
    }

    return firstFailure

